{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol-rich fraction of palm oil has poor oral bioavailability in humans; tocotrienols share a polar chromanol head and isoprenoid tail with the query's quinone head and decaprenyl tail, supporting low absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Lycopene, a highly lipophilic isoprenoid, showed only ~2.6% systemic availability after an oral capsule dose in humans, illustrating the absorption barrier for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene showed 58.5% absolute bioavailability in humans, indicating that some long-chain isoprenoids can be well absorbed; this is contradictory to a low prediction but is less transferable to the polar quinone-containing query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "13C-lycopene all-trans bioavailability was estimated at 23.2% in healthy adults, above the 20% threshold; this is contradictory to a low prediction but reflects a different measurement approach and compound structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is CoQ10, a highly lipophilic decaprenyl benzoquinone. Analogous evidence from tocotrienols and lycopene indicates poor oral bioavailability due to solubility and absorption limitations; phytoene's high bioavailability is less transferable. F is more likely below 20%.",
  "evidence_gaps": [
    "No direct CoQ10 absolute oral bioavailability record is present.",
    "No IV comparator or true absolute F measurement for the query is available.",
    "Formulation, fed/fasted state, and dose are unspecified for the query.",
    "Lycopene estimates vary widely by methodology, making true absorption versus systemic availability uncertain.",
    "Phytoene's high F may not transfer to CoQ10 due to differences in polar head group and molecular weight."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C02"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "phytoene/isoprenoid"
    },
    {
      "applicability": "high",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tocotrienol/isoprenoid chromanol"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C03"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lycopene/carotenoid"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C13"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "lycopene/carotenoid"
    }
  ],
  "revision_action": "initial"
}

